class Solution {
public:
    vector<vector<int>> sortMatrix(vector<vector<int>>& grid) {
        int n = (int)grid.size();
        for (int d = -(n - 1); d <= n - 1; ++d) {
            vector<int> vals;
            for (int i = 0; i < n; ++i) {
                int j = i - d;
                if (j >= 0 && j < n) vals.push_back(grid[i][j]);
            }
            if (d >= 0) sort(vals.begin(), vals.end(), greater<int>());
            else sort(vals.begin(), vals.end());
            int idx = 0;
            for (int i = 0; i < n; ++i) {
                int j = i - d;
                if (j >= 0 && j < n) grid[i][j] = vals[idx++];
            }
        }
        return grid;
    }
};
